  if v_package_id is null then insert into public.learning_packages(package_type, visibility, title, description, subject_area, active, version, metadata) values ('TECESCOLA', 'GLOBAL', 'Historia - Cronologia — Ordenar acontecimentos no tempo', 'Ordenar acontecimentos usando relacoes de anterioridade, duracao e simultaneidade.', 'HISTORY', false, 3, '{"content_pack":"tec-escola-knowledge-expansion-v3","content_version":3,"skill_code":"HISTORY_ORDER_EVENTS","curriculum_unit_id":"V5_HISTORY_CRONOLOGIA","mapping_status":"MAPPING_PENDING","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","student_available":false,"reused_existing_skill":true,"lesson_source":"V1_REUSED"}'::jsonb) returning id into v_package_id; else update public.learning_packages set title = 'Historia - Cronologia — Ordenar acontecimentos no tempo', description = 'Ordenar acontecimentos usando relacoes de anterioridade, duracao e simultaneidade.', active = false, version = 3, metadata = '{"content_pack":"tec-escola-knowledge-expansion-v3","content_version":3,"skill_code":"HISTORY_ORDER_EVENTS","curriculum_unit_id":"V5_HISTORY_CRONOLOGIA","mapping_status":"MAPPING_PENDING","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","student_available":false,"reused_existing_skill":true,"lesson_source":"V1_REUSED"}'::jsonb, updated_at = now() where id = v_package_id; end if;
