  insert into public.learning_question_bank(package_type, source_type, source_name, subject_area, domain, topic, statement, options, correct_answer, explanation, difficulty, estimated_minutes, provenance, metadata, active) select 'TECESCOLA', 'TECESCOLA_KNOWLEDGE_FACTORY_V3', 'TecEscola BNCC Knowledge Factory V3', 'PHYSICS', 'INTERACOES', 'PHYSICS_MODEL_FORCE', 'Um livro está parado sobre uma mesa. Qual afirmação descreve corretamente as forças verticais sobre o livro?', '["O peso desaparece enquanto o livro não se move.","A força normal da mesa e o peso atuam em sentidos opostos e podem se equilibrar.","Nenhuma força atua porque o livro está parado.","A força normal aponta para baixo e o peso para cima."]'::jsonb, '"A força normal da mesa e o peso atuam em sentidos opostos e podem se equilibrar."'::jsonb, 'O repouso indica aceleração vertical nula, não ausência de forças. A normal para cima pode equilibrar o peso para baixo.', 'EASY', 3, 'TECESCOLA_AUTHORED_CONTENT_STAGING_WITH_OFFICIAL_SOURCE_DOSSIERS_PENDING_HUMAN_REVIEW', '{"content_id":"V3_PHYS_FORCE_Q01","content_pack":"tec-escola-knowledge-expansion-v3","content_version":3,"skill_code":"PHYSICS_MODEL_FORCE","purpose":"PROBE","context_family":"ELEVATOR_SCALE","cognitive_process":"IDENTIFY","error_focus":"Repouso confundido com ausência de forças","remediation_hint":"Desenhe o peso para baixo e a normal da mesa para cima.","reused_from":null,"mapping_status":"MAPPING_PENDING","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","authoring_provenance":"TECESCOLA_AUTHORED_CONTENT_STAGING_WITH_OFFICIAL_SOURCE_DOSSIERS_PENDING_HUMAN_REVIEW"}'::jsonb, false where not exists (select 1 from public.learning_question_bank existing where existing.source_type = 'TECESCOLA_KNOWLEDGE_FACTORY_V3' and existing.metadata->>'content_id' = 'V3_PHYS_FORCE_Q01') returning id into v_question_id;
