  insert into public.learning_question_bank(package_type, source_type, source_name, subject_area, domain, topic, statement, options, correct_answer, explanation, difficulty, estimated_minutes, provenance, metadata, active) select 'TECESCOLA', 'TECESCOLA_KNOWLEDGE_FACTORY_V3', 'TecEscola BNCC Knowledge Factory V3', 'PHYSICS', 'INTERACOES', 'PHYSICS_MODEL_FORCE', 'Duas equipes puxam uma corda: 240 N para leste e 190 N para oeste. Qual é a resultante horizontal?', '["50 N para leste.","430 N para leste.","50 N para oeste.","Zero, pois há duas forças."]'::jsonb, '"50 N para leste."'::jsonb, 'Os sentidos são opostos; subtraímos os módulos e mantemos o sentido da força maior: 240 − 190 = 50 N para leste.', 'EASY', 3, 'TECESCOLA_AUTHORED_CONTENT_STAGING_WITH_OFFICIAL_SOURCE_DOSSIERS_PENDING_HUMAN_REVIEW', '{"content_id":"V3_PHYS_FORCE_Q02","content_pack":"tec-escola-knowledge-expansion-v3","content_version":3,"skill_code":"PHYSICS_MODEL_FORCE","purpose":"PRACTICE","context_family":"TUG_OF_WAR","cognitive_process":"CALCULATE","error_focus":"Soma de módulos em vetores opostos","remediation_hint":"Compare os sentidos antes de decidir se soma ou subtrai.","reused_from":null,"mapping_status":"MAPPING_PENDING","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","authoring_provenance":"TECESCOLA_AUTHORED_CONTENT_STAGING_WITH_OFFICIAL_SOURCE_DOSSIERS_PENDING_HUMAN_REVIEW"}'::jsonb, false where not exists (select 1 from public.learning_question_bank existing where existing.source_type = 'TECESCOLA_KNOWLEDGE_FACTORY_V3' and existing.metadata->>'content_id' = 'V3_PHYS_FORCE_Q02') returning id into v_question_id;
