  insert into public.learning_question_bank(package_type, source_type, source_name, subject_area, domain, topic, statement, options, correct_answer, explanation, difficulty, estimated_minutes, provenance, metadata, active) select 'TECESCOLA', 'TECESCOLA_KNOWLEDGE_FACTORY_V3', 'TecEscola BNCC Knowledge Factory V3', 'PHYSICS', 'INTERACOES', 'PHYSICS_MODEL_FORCE', 'Uma bicicleta segue para frente e o ciclista aciona o freio. Qual interpretação da força de atrito é mais adequada?', '["O atrito sempre aponta para frente quando há movimento.","O atrito elimina a massa da bicicleta.","Se a bicicleta ainda avança, a resultante necessariamente aponta para frente.","O atrito contrário ao movimento pode produzir resultante para trás e reduzir a velocidade."]'::jsonb, '"O atrito contrário ao movimento pode produzir resultante para trás e reduzir a velocidade."'::jsonb, 'A velocidade pode continuar para frente mesmo com aceleração para trás; o atrito de frenagem contribui para reduzir a rapidez.', 'MEDIUM', 3, 'TECESCOLA_AUTHORED_CONTENT_STAGING_WITH_OFFICIAL_SOURCE_DOSSIERS_PENDING_HUMAN_REVIEW', '{"content_id":"V3_PHYS_FORCE_Q03","content_pack":"tec-escola-knowledge-expansion-v3","content_version":3,"skill_code":"PHYSICS_MODEL_FORCE","purpose":"TRANSFER","context_family":"CYCLING_BRAKING","cognitive_process":"APPLY","error_focus":"Confundir sentido da velocidade com sentido da aceleração","remediation_hint":"Desenhe separadamente velocidade e força resultante.","reused_from":null,"mapping_status":"MAPPING_PENDING","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","authoring_provenance":"TECESCOLA_AUTHORED_CONTENT_STAGING_WITH_OFFICIAL_SOURCE_DOSSIERS_PENDING_HUMAN_REVIEW"}'::jsonb, false where not exists (select 1 from public.learning_question_bank existing where existing.source_type = 'TECESCOLA_KNOWLEDGE_FACTORY_V3' and existing.metadata->>'content_id' = 'V3_PHYS_FORCE_Q03') returning id into v_question_id;
