  if v_package_id is null then insert into public.learning_packages(package_type, visibility, title, description, subject_area, active, version, metadata) values ('TECESCOLA', 'GLOBAL', 'Leitura e producao multissemiótica — Planejar producao colaborativa em diferentes linguagens', 'Participa de processos de criação individual e colaborativa, selecionando linguagens e recursos para produzir sentidos em contexto definido.', 'LANGUAGES', false, 3, '{"content_pack":"tec-escola-knowledge-expansion-v3","content_version":3,"skill_code":"LANGUAGES_CREATE_COLLABORATIVELY_HS","curriculum_unit_id":"V3_LANGUAGES_MULTIMODAL_HS","mapping_status":"MAPPING_PENDING","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","student_available":false,"reused_existing_skill":false,"lesson_source":"V3_AUTHORED"}'::jsonb) returning id into v_package_id; else update public.learning_packages set title = 'Leitura e producao multissemiótica — Planejar producao colaborativa em diferentes linguagens', description = 'Participa de processos de criação individual e colaborativa, selecionando linguagens e recursos para produzir sentidos em contexto definido.', active = false, version = 3, metadata = '{"content_pack":"tec-escola-knowledge-expansion-v3","content_version":3,"skill_code":"LANGUAGES_CREATE_COLLABORATIVELY_HS","curriculum_unit_id":"V3_LANGUAGES_MULTIMODAL_HS","mapping_status":"MAPPING_PENDING","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","student_available":false,"reused_existing_skill":false,"lesson_source":"V3_AUTHORED"}'::jsonb, updated_at = now() where id = v_package_id; end if;
